// Scala Spark -- same logic as PySpark, different syntax

val df = spark.read.option("header","true").csv("/path/data.csv")

val result = df
  .filter(col("amount") > 1000)
  .groupBy("category")
  .agg(sum("amount").alias("total"))

result.write.mode("overwrite").parquet("/output/")

